<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{$company->name}} Interview Experience</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f8fd;color:#102445;font-family:Inter,system-ui,sans-serif}.hero{padding:55px 20px;background:#173e70;color:white}.wrap{width:min(960px,calc(100% - 32px));margin:auto}.hero a{color:#bcd7ff}.hero h1{font-size:40px;margin:14px 0}.summary{display:flex;gap:10px;flex-wrap:wrap}.summary span{background:#fff1;padding:8px 12px;border:1px solid #ffffff30;border-radius:20px}.main{padding:38px 0 70px}.panel,.round{background:white;border:1px solid #d8e4f2;border-radius:16px;padding:24px;margin-bottom:18px}.timeline{border-left:3px solid #78aaf0;margin-left:16px;padding-left:28px}.round{position:relative}.round:before{content:attr(data-number);position:absolute;left:-47px;top:22px;width:34px;height:34px;border-radius:50%;background:#286df0;color:white;display:grid;place-items:center;font-weight:900}.chips{display:flex;gap:7px;flex-wrap:wrap}.chips span{padding:6px 10px;background:#edf5ff;color:#1658b7;border-radius:18px;font-size:13px}.question{padding:12px;margin-top:9px;background:#f6f9fd;border-radius:8px}.salary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.salary-grid div{padding:15px;background:#f5f8fd;border-radius:10px}@media(max-width:600px){.salary-grid{grid-template-columns:1fr 1fr}}</style></head><body><section class="hero"><div class="wrap"><a href="{{route('company.experiences.company',$company->slug)}}">← {{$company->name}} experiences</a><h1>{{$experience->role?->role_name??'Interview experience'}}</h1><div class="summary"><span>{{$experience->location}}</span><span>{{ucwords(str_replace('_',' ',$experience->experience_level))}}</span><span>{{$experience->total_rounds}} rounds</span><span>{{ucfirst(str_replace('_',' ',$experience->difficulty))}}</span><span>{{ucfirst($experience->result)}}</span></div></div></section><main class="wrap main"><section class="panel"><h2>Candidate experience</h2><p>{!!nl2br(e($experience->overall_experience))!!}</p>@if($experience->duration_days!==null)<p><b>Process duration:</b> {{$experience->duration_days}} days</p>@endif</section><h2>Round-by-round process</h2><div class="timeline">@foreach($experience->rounds as $round)<article class="round" data-number="{{$round->round_number}}"><small>{{ucwords(str_replace('_',' ',$round->round_type))}}{{$round->duration_minutes?' · '.$round->duration_minutes.' minutes':''}}</small><h3>{{$round->round_name}}</h3><p>{!!nl2br(e($round->description))!!}</p>@if($round->topics)<h4>Topics</h4><div class="chips">@foreach($round->topics as $topic)<span>{{$topic}}</span>@endforeach</div>@endif @if($round->questions)<h4>Questions asked</h4>@foreach($round->questions as $question)<div class="question">{{$question}}</div>@endforeach @endif @if($round->candidate_experience)<h4>Candidate notes</h4><p>{{$round->candidate_experience}}</p>@endif</article>@endforeach</div>@if($experience->preparation_advice)<section class="panel"><h2>Preparation advice</h2><p>{!!nl2br(e($experience->preparation_advice))!!}</p></section>@endif @if($experience->package&&$experience->package->is_verified)<section class="panel"><h2>Reported compensation</h2><div class="salary-grid">@foreach(['base_salary'=>'Base salary','bonus'=>'Bonus','stock_value'=>'Stock','total_compensation'=>'Total compensation'] as $field=>$label)@if($experience->package->$field!==null)<div><small>{{$label}}</small><br><b>{{$experience->package->currency}} {{number_format($experience->package->$field)}}</b></div>@endif @endforeach</div><p><small>Candidate-reported and verified by moderation; compensation varies by role, level, location and date.</small></p></section>@endif</main></body></html>
